// AGENTS.md and SKILL.md are the source of truth for the managed Kinly agent
// and skill. The manifest needs them as strings, so this writes
// src/generated/instructions.ts from them. Run by build, typecheck and test;
// a test asserts the generated file matches the markdown.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const agents = readFileSync(path.join(root, "AGENTS.md"), "utf8");
const skill = readFileSync(path.join(root, "SKILL.md"), "utf8");
const out = `// GENERATED by scripts/gen-instructions.mjs from AGENTS.md and SKILL.md. Do not edit.\nexport const AGENTS_MD = ${JSON.stringify(agents)};\nexport const SKILL_MD = ${JSON.stringify(skill)};\n`;
mkdirSync(path.join(root, "src", "generated"), { recursive: true });
writeFileSync(path.join(root, "src", "generated", "instructions.ts"), out);
